#include <iostream>
#include <fstream>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    int n;
    int maxJedynki = 0, maxLiczba = 0;

    while (plik >> n) {
        int oryg = n;
        string bin = "";
        int jedynki = 0;
        int tmp = n;
        while (tmp > 0) {
            int bit = tmp % 2;
            bin += to_string(bit);
            if (bit == 1) jedynki++;
            tmp /= 2;
        }
        reverse(bin.begin(), bin.end());
        cout << oryg << " -> " << bin << " (jedynki: " << jedynki << ")" << endl;
        if (jedynki > maxJedynki) {
            maxJedynki = jedynki;
            maxLiczba = oryg;
        }
    }
    cout << "Najwiecej jedynek: " << maxLiczba << " (" << maxJedynki << " jedynek)" << endl;
    return 0;
}
```

